function threadOf(ref) {
    return ref.conversation.type === "channel"
        ? `${ref.conversation.id}:${ref.threadId}`
        : ref.conversation.id;
}
/**
 * One key per reply chain in a channel, and one per personal or group chat.
 * @experimental
 */
export function teamsThreadKey(ref) {
    return `teams:${threadOf(ref)}`;
}
/**
 * A Teams session principal. `"thread"` (default) lets anyone in the
 * thread continue the session and resolve its approvals; `"author"` scopes
 * both to the person who started it.
 * @experimental
 */
export function buildTeamsAuthContext(input) {
    const { conversation } = input.ref;
    // Tenant and object ids are GUIDs, so the principal uses one letter case for every message.
    const base = `teams:${conversation.tenantId?.toLowerCase() ?? "unknown"}:${threadOf(input.ref)}`;
    const user = input.author.aadObjectId?.toLowerCase() ?? input.author.id;
    const attributes = {
        conversation_type: conversation.type,
        conversation_id: conversation.id,
        thread_id: input.ref.threadId,
        user_id: input.author.id,
    };
    if (conversation.tenantId !== undefined) {
        attributes.tenant_id = conversation.tenantId;
    }
    if (conversation.teamId !== undefined) {
        attributes.team_id = conversation.teamId;
    }
    if (input.author.aadObjectId !== undefined) {
        attributes.aad_object_id = input.author.aadObjectId;
    }
    if (input.author.name !== undefined) {
        attributes.user_name = input.author.name;
    }
    if (input.author.isBot) {
        attributes.author_type = "bot";
    }
    if (input.engagement !== undefined) {
        attributes.engagement = input.engagement;
    }
    return {
        authenticator: "teams",
        principalId: input.respondTo === "author" ? `${base}:${user}` : base,
        principalType: "user",
        attributes,
        label: input.author.name,
    };
}
